```systemverilog
class mem_swap_seq extends uvm_sequence;
  `uvm_object_utils(mem_swap_seq)
  my_reg_block regm;          // contains uvm_mem mem with HDL path set
  function new(string name = "mem_swap_seq"); super.new(name); endfunction

  task body();
    uvm_status_e st; uvm_reg_data_t rd;
    int unsigned n = regm.mem.get_size();
    // 1. frontdoor write: data encodes the address (plus a tag so 0 is not 0)
    for (int a = 0; a < n; a++)
      regm.mem.write(st, a, 32'hA500_0000 | a, UVM_FRONTDOOR);
    // 2. backdoor peek of each physical row
    for (int a = 0; a < n; a++) begin
      regm.mem.peek(st, a, rd);
      if (rd != (32'hA500_0000 | a))
        `uvm_error("SWAP", $sformatf("row 0x%0h holds 0x%0h (written to logical 0x%0h)",
                                      a, rd, rd[23:0]))
    end
    // 3. frontdoor read back too: catches read-path-only faults
    for (int a = 0; a < n; a++) begin
      regm.mem.read(st, a, rd, UVM_FRONTDOOR);
      if (rd != (32'hA500_0000 | a)) `uvm_error("RD", $sformatf("addr 0x%0h read 0x%0h", a, rd))
    end
    // 4. reverse direction: poke via backdoor, read via frontdoor
    for (int a = 0; a < n; a++) regm.mem.poke(st, a, ~(32'hA500_0000 | a));
    for (int a = 0; a < n; a++) begin
      regm.mem.read(st, a, rd);
      if (rd != ~(32'hA500_0000 | a)) `uvm_error("BD2FD", $sformatf("addr 0x%0h", a))
    end
  endtask
endclass
```

### Explanation
- The **mismatch pattern localizes the bug**: if the wrong row's data is the address with two bits exchanged, it is an address-bit swap; a constant XOR means an inverted bit; data bits swapped means a data-lane swap.
- Step 4 (poke then frontdoor read) catches read-path-only errors; step 2 catches write-path errors; together they find faults even when write and read paths are both wrong.

