#include <stdio.h>

uint32_t reverse_bits(uint32_t x) {
    uint32_t out = 0;
    for (int i = 0; i < 32; i++) {
        out = (out << 1) | (x & 1u);
        x >>= 1;
    }
    return out;
}

/* O(log W) version: swap halves, then quarters, ... */
uint32_t reverse_bits_fast(uint32_t x) {
    x = (x >> 16) | (x << 16);
    x = ((x & 0xFF00FF00u) >> 8) | ((x & 0x00FF00FFu) << 8);
    x = ((x & 0xF0F0F0F0u) >> 4) | ((x & 0x0F0F0F0Fu) << 4);
    x = ((x & 0xCCCCCCCCu) >> 2) | ((x & 0x33333333u) << 2);
    x = ((x & 0xAAAAAAAAu) >> 1) | ((x & 0x55555555u) << 1);
    return x;
}

int main(void) {
    printf("%08X\n", reverse_bits(0x00000001u));      /* 80000000 */
    printf("%08X\n", reverse_bits(0x0000000Bu));      /* D0000000 */
    printf("%08X\n", reverse_bits_fast(0x12345678u)); /* 1E6A2C48 */
    return 0;
}
```

