#include <unordered_map>
#include <vector>

int digit_sum(long long x) {
    if (x < 0) x = -x;           // define behavior for negatives
    int s = 0;
    while (x) { s += x % 10; x /= 10; }
    return s;
}

long long count_equal_digit_sum_pairs(const std::vector<long long>& a) {
    std::unordered_map<int, long long> cnt;   // digit sum -> how many seen so far
    long long pairs = 0;
    for (long long x : a) {
        int s = digit_sum(x);
        pairs += cnt[s];                      // pair with every earlier match
        ++cnt[s];
    }
    return pairs;
