#include <iostream>
#include <string>
#include <unordered_map>

class CountingContainer {
public:
    void add(int v) { ++cnt_[v]; }

    bool exists(int v) const {
        auto it = cnt_.find(v);
        return it != cnt_.end() && it->second > 0;
    }

    long long get_count(int v) const {
        auto it = cnt_.find(v);          // NOT cnt_[v]: that would insert a zero entry
        return it == cnt_.end() ? 0 : it->second;
    }

    bool remove(int v) {                 // common follow-up operation
        auto it = cnt_.find(v);
        if (it == cnt_.end()) return false;
        if (--it->second == 0) cnt_.erase(it);
        return true;
    }

private:
    std::unordered_map<int, long long> cnt_;
};

int main() {
    CountingContainer c;
    c.add(5); c.add(7); c.add(5);
    std::cout << c.exists(5) << " " << c.exists(9) << " "
              << c.get_count(5) << " " << c.get_count(9) << "\n";   // 1 0 2 0
    c.remove(5); c.remove(5);
    std::cout << c.exists(5) << "\n";                                // 0
