**Key idea:** The sum of products of all pairs `i < j` in a range equals `(S² − Q) / 2`, where `S` is the range sum and `Q` the sum of squares. Keep `S` and `Q` in two Fenwick trees (or one segment tree), so both **point update** and **range query** are O(log n).

**Why:** `S² = Σ a_i² + 2 Σ_{i<j} a_i a_j`, so `Σ_{i<j} a_i a_j = (S² − Q) / 2`.

### Code
```cpp
#include <iostream>
#include <vector>
using ll = long long;

struct Fenwick {
    std::vector<ll> t;
    explicit Fenwick(int n) : t(n + 1, 0) {}
    void add(int i, ll d) { for (++i; i < (int)t.size(); i += i & -i) t[i] += d; }
    ll prefix(int i) const { ll s = 0; for (++i; i > 0; i -= i & -i) s += t[i]; return s; }   // sum [0..i]
    ll range(int l, int r) const { return prefix(r) - (l ? prefix(l - 1) : 0); }
};

class PairProduct {
public:
    explicit PairProduct(const std::vector<ll>& a) : a_(a), s_(a.size()), q_(a.size()) {
        for (int i = 0; i < (int)a.size(); ++i) { s_.add(i, a[i]); q_.add(i, a[i] * a[i]); }
    }
    void update(int i, ll v) {                      // a[i] = v
        s_.add(i, v - a_[i]);
        q_.add(i, v * v - a_[i] * a_[i]);
        a_[i] = v;
    }
    ll query(int l, int r) const {                  // sum of a_i*a_j, l <= i < j <= r
        ll S = s_.range(l, r), Q = q_.range(l, r);
        return (S * S - Q) / 2;                     // exact: S*S - Q is always even
    }
private:
    std::vector<ll> a_;
    Fenwick s_, q_;
};

int main() {
    PairProduct pp({1, 2, 3, 4});
    std::cout << pp.query(0, 2) << "\n";   // 1*2 + 1*3 + 2*3 = 11
    pp.update(1, 5);                       // array becomes [1,5,3,4]
    std::cout << pp.query(0, 2) << "\n";   // 5 + 3 + 15 = 23
    std::cout << pp.query(1, 3) << "\n";   // 15 + 20 + 12 = 47
}
```

