**Key idea:** Walk the list once, turning each `next` pointer around. Keep three pointers: `prev` (the already reversed part), `cur`, and `next` (saved before overwriting). O(n) time, O(1) space; return `prev` as the new head.

### Code
```cpp
#include <iostream>

struct Node { int val; Node* next; };

Node* reverse_list(Node* head) {
    Node* prev = nullptr;
    Node* cur = head;
    while (cur) {
        Node* nxt = cur->next;   // 1. save the rest
        cur->next = prev;        // 2. flip the pointer
        prev = cur;              // 3. advance prev
        cur = nxt;               // 4. advance cur
    }
    return prev;                 // new head
}

Node* reverse_rec(Node* head) {              // recursive, O(n) stack
    if (!head || !head->next) return head;
    Node* new_head = reverse_rec(head->next);
    head->next->next = head;
    head->next = nullptr;
    return new_head;
}

int main() {
    Node n3{3, nullptr}, n2{2, &n3}, n1{1, &n2};
    for (Node* p = reverse_list(&n1); p; p = p->next) std::cout << p->val << " ";   // 3 2 1
    std::cout << "\n";
}
```

