#include <iostream>
#include <iterator>
#include <map>

class IntervalSet {
public:
    // Insert closed interval [L, R]; touching intervals ([1,3] and [4,5]) are merged too.
    void add(long long L, long long R) {
        auto it = iv_.upper_bound(L);                 // first start > L
        if (it != iv_.begin()) {
            auto p = std::prev(it);
            if (p->second >= L - 1) it = p;           // previous one overlaps/touches
        }
        while (it != iv_.end() && it->first <= R + 1) {
            L = std::min(L, it->first);
            R = std::max(R, it->second);
            it = iv_.erase(it);
        }
        iv_[L] = R;
    }
    void print() const {
        for (auto& [s, e] : iv_) std::cout << "[" << s << "," << e << "] ";
        std::cout << "\n";
    }
private:
    std::map<long long, long long> iv_;
};

int main() {
