    s.add(1, 3);  s.print();    // [1,3]
    s.add(6, 8);  s.print();    // [1,3] [6,8]
    s.add(10, 12); s.print();   // [1,3] [6,8] [10,12]
    s.add(2, 7);  s.print();    // [1,8] [10,12]
    s.add(9, 9);  s.print();    // [1,12]  (touching merges)
}
